// ApplyDomain applies domain.User fields to the UserUpdate builder.
// Chain .Where(...) conditions to target specific records.
//
// Note: ctx is accepted for API symmetry with ApplyDomainCreate/UpdateOne and
// to allow future ctx-aware field transformers. Currently no transformer hooks
// fire here — the error return is always nil.
func (u *UserUpdate) ApplyDomain(ctx context.Context, d *domain.User, opts ...entdomain.ApplyOption) (*UserUpdate, error) {
	cfg := entdomain.NewApplyConfig(opts...)
	_ = cfg
	_ = ctx
	if cfg.ShouldApply("name", d.Name) {
		u = u.SetName(d.Name)
	}
	if cfg.ShouldApplyPtr("bio", d.Bio) && d.Bio != nil {
		u = u.SetBio(*d.Bio)
	}
	if cfg.ShouldApply("status", d.Status) {
		u = u.SetStatus(user.Status(d.Status))
	}
	if cfg.ShouldApplyPtr("score", d.Score) && d.Score != nil {
		u = u.SetScore(*d.Score)
	}
	if cfg.ShouldApply("external_id", d.ExternalID) {
		u = u.SetExternalID(d.ExternalID)
	}
	if cfg.ShouldApplyPtr("updated_at", d.UpdatedAt) && d.UpdatedAt != nil {
		u = u.SetUpdatedAt(*d.UpdatedAt)
	}
	if cfg.ShouldApply("settings", d.Settings) {
		u = u.SetSettings(d.Settings)
	}
	if cfg.ShouldApply("labels", d.Labels) {
		u = u.SetLabels(d.Labels)
	}
	if cfg.ShouldApply("tag_names", d.TagNames) {
		u = u.SetTagNames(d.TagNames)
	}
	if cfg.ShouldApply("metadata", d.Metadata) {
		u = u.SetMetadata(d.Metadata)
	}
	if cfg.IsAppendEdge("post_ids") {
		u = u.AddPostIDs(d.PostIDs...)
	} else {
		u = u.ClearPosts().AddPostIDs(d.PostIDs...)
	}
	if cfg.IsAppendEdge("tag_ids") {
		u = u.AddTagIDs(d.TagIDs...)
	} else {
		u = u.ClearTags().AddTagIDs(d.TagIDs...)
	}
	return u, nil
}

